#include <iostream>
#include <cmath>
#include <stdexcept>
class Complex{double r,i;public:Complex():r(0),i(0){}Complex(double a):r(a),i(0){}Complex(double a,double b):r(a),i(b){}Complex operator+(const Complex&z)const{return {r+z.r,i+z.i};}Complex operator-(const Complex&z)const{return {r-z.r,i-z.i};}Complex operator*(const Complex&z)const{return {r*z.r-i*z.i,r*z.i+i*z.r};}Complex operator/(const Complex&z)const{double d=z.r*z.r+z.i*z.i;if(d==0)throw std::domain_error("division by zero impedance");return {(r*z.r+i*z.i)/d,(i*z.r-r*z.i)/d};}bool operator==(const Complex&z)const{return std::abs(r-z.r)<1e-9&&std::abs(i-z.i)<1e-9;}double mag()const{return std::hypot(r,i);}friend std::ostream&operator<<(std::ostream&o,const Complex&z){return o<<z.r<<(z.i<0?" - j":" + j")<<std::abs(z.i);}};
int main(){double pi=std::acos(-1),w=2*pi*50;Complex R(10),L(0,w*.01),C(0,-1/(w*.001));Complex series=R+L+C,parallel=(R*L)/(R+L);std::cout<<"ZR="<<R<<"\nZL="<<L<<"\nZC="<<C<<"\nSeries="<<series<<" |Z|="<<series.mag()<<"\nParallel R-L="<<parallel<<" |Z|="<<parallel.mag()<<'\n';try{auto x=R/Complex();std::cout<<x;}catch(const std::exception&e){std::cout<<"Caught: "<<e.what()<<'\n';}}
